rc={r['id']:r for r in json.loads((L/'outputs/fetch-receipts.json').read_text()) if 'sha256' in r}
def src(*ks): return {k:{'file':rc[k]['file'],'url':rc[k]['url'],'sha256':rc[k]['sha256']} for k in ks if k in rc}
